# so repetition loops are always bounded by the length of the text)
# ---------------------------------------------------------------------------


def _atom_matches(atom, ch: str) -> bool:
    kind = atom[0]
    if kind == "lit":
        return ch == atom[1]
    if kind == "any":
        return True
    negated, members, ranges = atom[1]
    found = ch in members
    if not found:
        for lo, hi in ranges:
            if lo <= ch <= hi:
                found = True
                break
    return (not found) if negated else found


def _match(pieces, pi: int, text: str, pos: int) -> bool:
    if pi == len(pieces):
        return pos == len(text)
    atom, lo, hi = pieces[pi]
    return _repeat(pieces, pi, atom, lo, hi, text, pos, 0)


def _repeat(pieces, pi, atom, lo, hi, text, pos: int, count: int) -> bool:
    # Greedy: try consuming one more character first, then back off.
    if count < hi and pos < len(text) and _atom_matches(atom, text[pos]):
        if _repeat(pieces, pi, atom, lo, hi, text, pos + 1, count + 1):
            return True
    if count >= lo:
        return _match(pieces, pi + 1, text, pos)
    return False


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


class Match:
    """A successful full match; the matched span is always the whole text."""

    __slots__ = ("string",)

    def __init__(self, text: str) -> None:
        self.string = text

    def group(self, index: int = 0) -> str:
        if index != 0:
            raise IndexError("no such group")
        return self.string

    def start(self) -> int:
        return 0

    def end(self) -> int:
        return len(self.string)

    def span(self) -> tuple[int, int]:
        return (0, len(self.string))

    def __repr__(self) -> str:
        return f"<Match {self.string!r}>"


class Pattern:
    """A compiled pattern, reusable across any number of texts."""

    __slots__ = ("pattern", "_pieces")

    def __init__(self, pattern: str, pieces) -> None:
        self.pattern = pattern
        self._pieces = pieces

    def fullmatch(self, text: str):
        if not isinstance(text, str):
            raise TypeError("text must be a str")
        if _match(self._pieces, 0, text, 0):
            return Match(text)
        return None

    def __repr__(self) -> str:
        return f"<Pattern {self.pattern!r}>"


def compile(pattern: str) -> Pattern:
    """Compile a pattern string into a reusable :class:`Pattern`."""
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a str")
    return Pattern(pattern, _parse(pattern))


def fullmatch(pattern: str, text: str):
    """Compile ``pattern`` and match it against the whole of ``text``."""
    return compile(pattern).fullmatch(text)

