        else:
            c = rng.choice(CLASS_CHARS)
            if c in "-]^\\":
                parts.append("\\" + c)
            else:
                parts.append(c)
    return "[" + ("^" if neg else "") + "".join(parts) + "]"


def gen_atom(rng):
    r = rng.random()
    if r < 0.4:
        c = rng.choice(LITERALS + ["好", "\n"])
        return c
    if r < 0.55:
        return "."
    if r < 0.7:
        return "\\" + rng.choice(META)
    return gen_class(rng)


