            pass
        elif q < 0.55:
            a += "?"
        elif q < 0.7:
            a += "*"
        elif q < 0.8:
            a += "+"
        else:
            m = rng.randint(0, 4)
            style = rng.randint(0, 2)
            if style == 0:
                a += "{" + str(m) + "}"
            elif style == 1:
                a += "{" + str(m) + ",}"
            else:
                a += "{" + str(m) + "," + str(m + rng.randint(0, 3)) + "}"
        out.append(a)
    return "".join(out)


def gen_text(rng):
    return "".join(rng.choice(TEXT_ALPHABET) for _ in range(rng.randint(0, 8)))


